    # L1 = a sin^2 x, L2 = b cos^2 x, L3 = c sin x cos x
    # In terms of t = tan x (>0): sin^2 = t^2/(1+t^2), cos^2 = 1/(1+t^2), sin*cos = t/(1+t^2)
    # Triangle fails if any of:
    # 1) a t^2 >= b + c t  -> f1(t) >= 0 with f1(t)=a t^2 - c t - b
    # 2) b >= a t^2 + c t  -> f2(t) <= 0 with f2(t)=a t^2 + c t - b
    # 3) c t >= a t^2 + b  -> f3(t) <= 0 with f3(t)=a t^2 - c t + b
    # Roots and violating t-intervals:
    Dp = c*c + 4*a*b
    r1 = (c + math.sqrt(Dp)) / (2*a)  # positive root of f1
    r2 = (math.sqrt(Dp) - c) / (2*a)  # positive root of f2
    total_measure = 0.0
    # S1: t in [r1, +inf) maps to x in [atan(r1), pi/2)
    total_measure += (math.pi/2 - math.atan(r1))
    # S2: t in (0, r2] maps to x in (0, atan(r2)]
    total_measure += math.atan(r2)
    # S3 exists only if Delta > 0
    Delta = c*c - 4*a*b
    if Delta > 0:
        sqrtD = math.sqrt(Delta)
        r3m = (c - sqrtD) / (2*a)
        r3p = (c + sqrtD) / (2*a)
        if r3m <= 0 or r3p <= 0:
            # Shouldn't happen for positive a,b,c with Delta>0, but guard anyway
            return (False, None)
        total_measure += (math.atan(r3p) - math.atan(r3m))
    # Probability as fraction of total angle length (pi/2)
    p_geom = total_measure / (math.pi/2)
    # Closed-form reference for c^2 <= 4ab: p = deg(arctan((a+b)/c))/90 = atan((a+b)/c)/(pi/2)
    # For Delta > 0, the general form adds the middle interval, which simplifies to:
    # p = 1 - [atan(c/(a+b)) - atan(sqrt(Delta)/(a+b))]/(pi/2)
    if Delta <= 0:
        p_ref = math.atan((a + b) / c) / (math.pi/2)
    else:
        p_ref = 1.0 - (math.atan(c / (a + b)) - math.atan(math.sqrt(Delta) / (a + b))) / (math.pi/2)
    # Check consistency within tight tolerance
    if not (abs(p_geom - p_ref) < 1e-12):
        return (False, None)
    # Also, for our intended family we enforce Delta <= 0 to guarantee the elegant identity and integer m
    if Delta > 0:
        return (False, None)
    # Final answer is m + n
    answer = m + n
    return (True, answer)


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
            """Return dict with assignment/question/answer or raise RuntimeError."""
            start = time.time()
            attempts = 0
            while time.time() - start < timeout_seconds:
                attempts += 1
                rng = _RNGShim(seed + attempts)
                assignment = generator(rng)
                valid, answer = verifier(assignment)
                if valid:
                    question = LANGUAGE_WRAPPER.format(**assignment)
